    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Aliving systematic review is a form of evidence synthesis which is updated regularly when sufficient new evidence becomes available [60]. Two reviewers will independently search the updated published and unpublished evidence every six months and include all relevant articles as per the previously described inclusion criteria. The meta-analysis will be updated continuously depending on the availability of new evidence and will be published as a separate publication.",
      "reason": "This supports that the review is a “living” systematic review (i.e., update status), which is the kind of supplementary information that can appear in the title."
    }
  ],
  "confidence": 72
}

